def _make_watch_git() -> Git:
    class _UnitWatchGit(Git):
        def __init__(self) -> None:
            self.repo_dir = Path("/watch-test-repo")
            self._cache = None

        def _unexpected_git_subprocess(self, method_name: str) -> AssertionError:
            return AssertionError(
                f"{method_name} should not be reached in unit tests; "
                "patch the watch git seam instead of spawning real git subprocesses"
            )

        def _run(self, *args: object, **kwargs: object) -> object:  # type: ignore[override]
            raise self._unexpected_git_subprocess("_run")

        def _run_readonly_cached(self, *args: object, **kwargs: object) -> object:  # type: ignore[override]
            raise self._unexpected_git_subprocess("_run_readonly_cached")

        def _run_readonly_success_cached(self, *args: object, **kwargs: object) -> object:  # type: ignore[override]
            raise self._unexpected_git_subprocess("_run_readonly_success_cached")

    git = _UnitWatchGit()
    git.default_branch = MagicMock(return_value="main")  # type: ignore[method-assign]
    git.current_branch = MagicMock(return_value="main")  # type: ignore[method-assign]
    git.local_branch_names = MagicMock(return_value=frozenset({"main"}))  # type: ignore[method-assign]
    git.branch_exists = MagicMock(return_value=True)  # type: ignore[method-assign]
    git.branches_exist = MagicMock(return_value={})  # type: ignore[method-assign]
    git.ref_exists = MagicMock(return_value=False)  # type: ignore[method-assign]
    git.rev_parse_if_exists = MagicMock(  # type: ignore[method-assign]
        side_effect=lambda ref: "watchtestheadsha" if ref == "HEAD" else None
    )
    git.resolve_refs = MagicMock(return_value={})  # type: ignore[method-assign]
    git.worktree_list = MagicMock(return_value=[{"path": str(git.repo_dir)}])  # type: ignore[method-assign]
    git.can_merge = MagicMock(return_value=True)  # type: ignore[method-assign]
    git.is_merged = MagicMock(return_value=False)  # type: ignore[method-assign]
    git.count_commits_ahead = MagicMock(return_value=1)  # type: ignore[method-assign]
    git.count_commits_ahead_checked = MagicMock(return_value=1)  # type: ignore[method-assign]
    git.has_non_empty_source_diff_against_target = MagicMock(return_value=True)  # type: ignore[method-assign]
    git.get_diff_name_status = MagicMock(return_value="M\tfeature.txt\n")  # type: ignore[method-assign]
    git.get_diff_stat_parsed = MagicMock(return_value=(1, 1, 0))  # type: ignore[method-assign]
    git.get_diff_numstat = MagicMock(return_value="1\t0\tfeature.txt\n")  # type: ignore[method-assign]
    return git


def _live_settle_results(
    pending_starts: list[object],
    *,
    store,
) -> list[object]:
    return [
        watch_module._WatchDispatchSettleResult(
            entry=entry,
            status=watch_module._DispatchSettleStatus.LIVE,
            reason=f"task {getattr(entry, 'task_id', None)} reached running state",
            task=store.get(getattr(entry, "task_id", "")),
        )
        for entry in pending_starts
    ]


def _setup_retry_limit_parked_lineage(tmp_path: Path) -> tuple[object, Config, DbTask, DbTask]:
    setup_config(tmp_path)
    store = make_store(tmp_path)

    impl = store.add("Implement feature", task_type="implement")
    assert impl.id is not None
    impl.status = "completed"
    impl.completed_at = datetime.now(UTC)
    impl.branch = "feature/parked-retry-limit"
    impl.has_commits = True
    store.update(impl)
    store.set_merge_status(impl.id, "unmerged")

    review = store.add("Review feature", task_type="review", depends_on=impl.id)
    assert review.id is not None
    review.status = "completed"
    review.completed_at = datetime.now(UTC)
    review.output_content = "**Verdict: CHANGES_REQUESTED**\n\nPlease fix."
    store.update(review)

    failed_improve = store.add(
        "Failed improve",
        task_type="improve",
        depends_on=review.id,
        based_on=impl.id,
        same_branch=True,
    )
    assert failed_improve.id is not None
    failed_improve.status = "failed"
    failed_improve.failure_reason = "MAX_TURNS"
    failed_improve.session_id = "sess-parked-improve"
    failed_improve.branch = impl.branch
    failed_improve.completed_at = datetime.now(UTC)
    store.update(failed_improve)

    exhausted_improve = store.add(
        "Failed retry improve",
        task_type="improve",
        depends_on=review.id,
        based_on=failed_improve.id,
        same_branch=True,
    )
    assert exhausted_improve.id is not None
    exhausted_improve.status = "failed"
    exhausted_improve.failure_reason = "TIMEOUT"
    exhausted_improve.session_id = failed_improve.session_id
    exhausted_improve.branch = impl.branch
    exhausted_improve.completed_at = datetime.now(UTC)
    store.update(exhausted_improve)

    config = Config.load(tmp_path)
    return store, config, impl, exhausted_improve


def _setup_verify_fix_failed_parked_owner(tmp_path: Path) -> tuple[object, Config, DbTask, str]:
    from gza.review_tasks import create_or_reuse_verify_fix_task
    from gza.review_verify_state import VerifyEpoch

    setup_config(tmp_path)
    store = make_store(tmp_path)
    config = Config.load(tmp_path)
    config.verify_command = "./bin/tests"
    config.autonomous_verify_timeout_seconds = 120
    config.review_verify_timeout_grace_seconds = 5.0

    impl = store.add("Implement verify fix failed park", task_type="implement")
    assert impl.id is not None
    impl.status = "completed"
    impl.completed_at = datetime.now(UTC)
    impl.branch = "feature/parked-verify-fix-failed"
    impl.has_commits = True
    store.update(impl)
    store.set_merge_status(impl.id, "unmerged")

    head_sha = "verify-fix-failed-head"
    output_artifact = store_command_output_artifact(
        store,
        impl,
        config,
        kind="verify_command_output",
        producer="test",
        label="verify_command_output",
        output="pytest failed",
        command="./bin/tests",
        status="failed",
        exit_status="1",
        head_sha=head_sha,
        created_at=datetime(2026, 7, 6, 12, 0, tzinfo=UTC),
    )
    persist_verify_gate_artifact(
        store,
        config,
        owner_task=impl,
        source_task=impl,
        result=_make_review_verify_result(
            "./bin/tests",
            status="failed",
            exit_status="1",
            captured_at=datetime(2026, 7, 6, 12, 0, tzinfo=UTC),
            reviewed_branch=impl.branch,
            reviewed_head_sha=head_sha,
            reviewed_base_sha="base-head",
            working_directory=str(tmp_path),
            failure="pytest failed",
        ),
        verify_timeout_seconds=120,
        verify_timeout_grace_seconds=5.0,
        output_artifact_id=output_artifact.id,
        output_artifact_task_id=impl.id,
        output_artifact_path=output_artifact.path,
        producer="test",
    )
    epoch = VerifyEpoch(
        reviewed_branch=impl.branch,
        reviewed_head_sha=head_sha,
        verify_command="./bin/tests",
        verify_timeout_seconds=120,
        verify_timeout_grace_seconds=5.0,
    )
    verify_fix, _created = create_or_reuse_verify_fix_task(
        store,
        config,
        impl_task=impl,
        based_on_task=impl,
        verify_epoch=epoch,
        trigger_source="test",
    )
    verify_fix.status = "completed"
    verify_fix.completed_at = datetime(2026, 7, 6, 12, 5, tzinfo=UTC)
    verify_fix.branch = impl.branch
    verify_fix.has_commits = True
    store.update(verify_fix)
    return store, config, impl, head_sha


def test_behavior_monitor_internal_task_does_not_consume_watch_slots(tmp_path: Path) -> None:
    setup_config(tmp_path)
    store = make_store(tmp_path)
    config = Config.load(tmp_path)

    internal = store.add(
        "Behavior monitor check",
        task_type="internal",
        tags=("behavior-monitor", "behavior-conformance"),
        skip_learnings=True,
    )
    assert internal.id is not None
    internal.status = "in_progress"
    internal.started_at = datetime.now(UTC)
    internal.running_pid = os.getpid()
    store.update(internal)

    with patch("gza.cli.watch._analyze_watch_cycle", return_value=_empty_scoped_watch_plan().analysis):
        plan = watch_module._build_watch_cycle_plan(
            config=config,
            store=store,
            batch=1,
            tags=None,
            any_tag=False,
            recovery_slots=0,
            recovery_mode=None,
            max_recovery_attempts=1,
        )

    assert plan.running == 0
    assert plan.running_task_ids == ()
    assert plan.slots == 1


