@pytest.mark.parametrize("terminal_status", ["completed", "failed"])
def test_watch_cycle_recovery_launch_terminal_before_confirmation_boundary_does_not_emit_start_failed(
    tmp_path: Path,
    terminal_status: str,
) -> None:
    setup_config(tmp_path)
