def test_watch_cycle_needs_rebase_followup_does_not_start_unplanned_retry(
    tmp_path: Path,
) -> None:
    setup_config(tmp_path)
    store = make_store(tmp_path)
    config = Config.load(tmp_path)
    log = _WatchLog(tmp_path / ".gza" / "watch.log", quiet=True)

    failed_rebase = store.add("Failed task needing rebase", task_type="implement")
    assert failed_rebase.id is not None
    failed_rebase.status = "failed"
    failed_rebase.failure_reason = "REBASE_REQUIRED"
    failed_rebase.completed_at = datetime.now(UTC)
    failed_rebase.branch = "feature/recovery-needs-rebase"
    store.update(failed_rebase)

    failed_retry = store.add("Failed task needing retry", task_type="implement")
    assert failed_retry.id is not None
    failed_retry.status = "failed"
    failed_retry.failure_reason = "PROVIDER_ERROR"
    failed_retry.completed_at = datetime.now(UTC)
    failed_retry.branch = "feature/recovery-retry"
    store.update(failed_retry)

    retry_child = store.add(
        failed_retry.prompt,
        task_type="implement",
        based_on=failed_retry.id,
        recovery_origin="retry",
    )
    assert retry_child.id is not None

    rebase_child = store.add("Generated rebase task", task_type="rebase", based_on=failed_rebase.id)
    assert rebase_child.id is not None

    def _recovery_row(task: Task) -> LineageOwnerRow:
        return LineageOwnerRow(
            owner_task=task,
            members=(task,),
            tree=None,
            lineage_status="actionable",
            next_action=None,
            next_action_reason="",
            unresolved_tasks=(task,),
            unresolved_leaf_summary=(),
            lifecycle_action_task=None,
            recovery_action_task=task,
            recovery_leaf_task=task,
        )

    rebase_row = _recovery_row(failed_rebase)
    retry_row = _recovery_row(failed_retry)
    needs_rebase_decision = FailedRecoveryDecision(
        task_id=failed_rebase.id,
        action="reconcile",
        reason_code="recovery_preflight_rebase",
        reason_text="Needs rebase before retry",
        launch_mode="worker",
        attempt_index=1,
        attempt_limit=2,
    )
    retry_decision = FailedRecoveryDecision(
        task_id=failed_retry.id,
        action="retry",
        reason_code="retry_provider_error",
        reason_text="Retry failed implementation",
        launch_mode="worker",
        attempt_index=1,
        attempt_limit=2,
        recovery_task_id=retry_child.id,
        reuse_existing=True,
    )
    precomputed_plan = _WatchCyclePlan(
        running_task_ids=(),
        anonymous_worker_count=0,
        pending_count=0,
        blocked_pending_count=0,
        running=0,
        effective_batch=1,
        slots=1,
        analysis=_WatchCycleAnalysis(
            target_branch="main",
            scope_gaps=(),
            owner_rows=(rebase_row, retry_row),
            watch_read_context=RecoveryReadContext(),
            lifecycle_rows=(),
            recovery_rows=(rebase_row, retry_row),
            recovery_lane_entry_by_failed_id={},
            action_plan=(),
            recovery_attention_rows=(),
            recovery_visible_skips=(),
            actionable_failed=(
                (
                    rebase_row,
                    failed_rebase,
                    needs_rebase_decision,
                    {
                        "type": "needs_rebase",
                        "description": "Queue rebase before retry",
                        "reason": "recovery-preflight-rebase",
                    },
                    True,
                    failed_rebase,
                ),
                (
                    retry_row,
                    failed_retry,
                    retry_decision,
                    {"type": "retry", "description": "Retry failed task"},
                    True,
                    failed_retry,
                ),
            ),
        ),
    )

    def _fake_execute_advance_action(*, task, action, context):
        del context
        assert task.id == failed_rebase.id
        assert action["type"] == "needs_rebase"
        rebase_child.status = "in_progress"
        rebase_child.session_id = f"session-{rebase_child.id}"
        store.update(rebase_child)
        return AdvanceActionExecutionResult(
            action_type="needs_rebase",
            status="success",
            message="Created rebase task for retry path",
            success_message="Created rebase task for retry path",
            worker_label="rebase",
            worker_consuming=False,
            work_done=True,
            created_task=rebase_child,
        )

    def _fake_spawn_background_worker(
        _args: argparse.Namespace,
        _config: Config,
        *,
        task_id: str,
        **_kwargs: object,
    ) -> int:
        pytest.fail(f"needs_rebase follow-up should settle via execute_advance_action, not spawn worker {task_id}")
        return 0

    with (
        patch("gza.cli._common.reconcile_in_progress_tasks"),
        patch("gza.cli._common.prune_terminal_dead_workers"),
        patch("gza.cli._common.reconcile_dead_pending_recovery_tasks"),
        patch("gza.cli.watch.Git", return_value=_make_watch_git()),
        patch("gza.cli.watch.launch_permit"),
        patch(
            "gza.cli.watch.check_main_integration_verify",
            return_value=SimpleNamespace(
                merges_halted=False,
                state=SimpleNamespace(task=SimpleNamespace(id=None), alert_message=None),
            ),
        ),
        patch(
            "gza.cli.watch.build_dispatch_preview",
            return_value=DispatchPreview(
                entries=(
                    DispatchPreviewEntry(
                        lane="recovery",
                        task=failed_rebase,
                        owner_task=failed_rebase,
                        runnable=True,
                        worker_consuming=True,
                        decision=needs_rebase_decision,
                        advance_action={"type": "needs_rebase"},
                        lineage_row=rebase_row,
                    ),
                    DispatchPreviewEntry(
                        lane="recovery",
                        task=failed_retry,
                        owner_task=failed_retry,
                        runnable=True,
                        worker_consuming=True,
                        decision=retry_decision,
                        advance_action={"type": "retry"},
                        lineage_row=retry_row,
                    ),
                )
            ),
        ),
        patch("gza.cli.watch.execute_advance_action", side_effect=_fake_execute_advance_action),
        patch("gza.cli.watch._prepare_task_for_immediate_execution", side_effect=lambda _config, task, **_kwargs: task),
        patch("gza.cli.watch._spawn_background_worker", side_effect=_fake_spawn_background_worker),
        patch(
            "gza.cli.watch._settle_watch_dispatch_starts",
            side_effect=lambda *, pending_starts, **_kwargs: _live_settle_results(pending_starts, store=store),
        ),
    ):
        result = _run_cycle(
            config=config,
            store=store,
            batch=1,
            max_iterations=10,
            dry_run=False,
            log=log,
            recovery_slots=1,
            max_recovery_attempts=config.max_resume_attempts,
            precomputed_plan=precomputed_plan,
        )

    assert result.work_done is True
    assert result.confirmed_start_count == 1
    refreshed_rebase_child = store.get(rebase_child.id)
    refreshed_retry_child = store.get(retry_child.id)
    assert refreshed_rebase_child is not None
    assert refreshed_retry_child is not None
    assert refreshed_rebase_child.status == "in_progress"
    assert refreshed_retry_child.status == "pending"


def test_watch_cycle_replan_settles_only_new_recovery_starts(
    tmp_path: Path,
) -> None:
    setup_config(tmp_path)
    store = make_store(tmp_path)
    config = Config.load(tmp_path)
    log_path = tmp_path / ".gza" / "watch.log"
    log = _WatchLog(log_path, quiet=True)

    failed_retry_first = store.add("Failed retry first", task_type="implement")
    assert failed_retry_first.id is not None
    failed_retry_first.status = "failed"
    failed_retry_first.failure_reason = "PROVIDER_ERROR"
    failed_retry_first.completed_at = datetime.now(UTC)
    failed_retry_first.branch = "feature/replan-first-retry"
    store.update(failed_retry_first)

    failed_reconcile = store.add("Failed reconcile", task_type="implement")
    assert failed_reconcile.id is not None
    failed_reconcile.status = "failed"
    failed_reconcile.failure_reason = "BRANCH_UNPUSHABLE"
    failed_reconcile.completed_at = datetime.now(UTC)
    failed_reconcile.branch = "feature/replan-reconcile"
