def test_watch_cycle_dirty_checkout_blocks_merge_pass_and_stops_later_merges(tmp_path: Path) -> None:
    setup_config(tmp_path)
    store = make_store(tmp_path)

    first = store.add("First completed task", task_type="implement")
    second = store.add("Second completed task", task_type="implement")
    for task, branch in ((first, "feature/watch-dirty-1"), (second, "feature/watch-dirty-2")):
        assert task.id is not None
        task.status = "completed"
        task.completed_at = datetime.now(UTC)
        task.branch = branch
        store.update(task)
        store.set_merge_status(task.id, "unmerged")

    config = Config.load(tmp_path)
    log_path = tmp_path / ".gza" / "watch.log"
    log = _WatchLog(log_path, quiet=True)
    git = _make_watch_git()

    calls: list[str] = []

    def fake_execute_merge_action(*args, **kwargs):
        task = args[3]
        calls.append(task.id)
        return SimpleNamespace(
            rc=1,
            status="blocked_dirty_checkout",
            block_reason="main checkout has uncommitted changes",
            created_followups=[],
            reused_followups=[],
        )

    with (
        patch("gza.cli._common.reconcile_in_progress_tasks"),
        patch("gza.cli._common.prune_terminal_dead_workers"),
        patch("gza.cli.watch.Git", return_value=git),
        patch("gza.cli.watch.determine_next_action", return_value={"type": "merge"}),
        patch("gza.cli.watch._execute_merge_action", side_effect=fake_execute_merge_action),
    ):
        result = _run_cycle_and_emit_transition_events(
            config=config,
            store=store,
            batch=2,
            max_iterations=10,
            dry_run=False,
            log=log,
            quiet=True,
        )

    assert result.work_done is False
    assert len(calls) == 1
    assert calls[0] in {first.id, second.id}
    assert "ATTENTION merges blocked: main checkout has uncommitted changes - commit or stash them first" in (
        log_path.read_text()
    )


def test_watch_cycle_blocked_candidate_verify_emits_sticky_attention_and_leaves_task_unmerged(
    tmp_path: Path,
) -> None:
    setup_config(tmp_path)
    store = make_store(tmp_path)

    task = _make_completed_watch_merge_task(
        store,
        "Completed task",
        branch="feature/watch-candidate-blocked",
    )

    config = Config.load(tmp_path)
    log_path = tmp_path / ".gza" / "watch.log"
    log = _WatchLog(log_path, quiet=True)
    git = _make_watch_git()

    blocked_result = SimpleNamespace(
        rc=1,
        status="blocked_candidate_verify",
        block_reason="candidate verify red; refusing to promote while phase `unit` is failing",
        candidate_verify=CandidateIntegrationVerifyCheck(
            evidence=CandidateIntegrationVerifyEvidence(
                gate_enabled=True,
                verify_command="./bin/tests",
                verify_timeout_seconds=300,
                verify_timeout_grace_seconds=5.0,
                environment_identity=MainIntegrationVerifyEnvironmentIdentity(
                    runner_class="host",
                    platform_system="Darwin",
                    platform_machine="arm64",
                    python_implementation="CPython",
                    python_version=f"{sys.version_info.major}.{sys.version_info.minor}",
                ),
                tree_fingerprint="fp-darwin-candidate",
                head_sha="isolated-merge-oid",
                verify_status="failed",
                verify_exit_status="1",
                failure="worker died in host-only unit path",
                failing_phase="unit",
                reviewed_branch="main",
                working_directory=str(tmp_path),
                captured_at=datetime.now(UTC),
            ),
            classification="deterministic_red",
            merges_halted=True,
            remediation=None,
            verify_runs=2,
        ),
        created_followups=[],
        reused_followups=[],
    )

    with (
        patch("gza.cli._common.reconcile_in_progress_tasks"),
        patch("gza.cli._common.prune_terminal_dead_workers"),
        patch("gza.cli.watch.Git", return_value=git),
        patch("gza.cli.watch.determine_next_action", return_value={"type": "merge"}),
        patch("gza.cli.watch._execute_merge_action", return_value=blocked_result),
    ):
        first = _run_cycle_and_emit_transition_events(
            config=config,
            store=store,
            batch=1,
            max_iterations=10,
            dry_run=False,
            log=log,
            quiet=True,
        )
        second = _run_cycle_and_emit_transition_events(
            config=config,
            store=store,
            batch=1,
            max_iterations=10,
            dry_run=False,
            log=log,
            quiet=True,
        )

    assert first.work_done is False
    assert second.work_done is False
    refreshed = store.get(task.id)
    assert refreshed is not None
    assert refreshed.merge_status == "unmerged"
    log_text = log_path.read_text()
    assert (
        "ATTENTION "
        f"{task.id}: candidate verify blocked promotion on fp-darwin-candidate; phase `unit` failed before main changed"
    ) in log_text
    assert sum(1 for line in log_text.splitlines() if "ATTENTION " in line and "fp-darwin-candidate" in line) == 1


